"""Tests for the unified error_json helper."""

import json

import pytest

from agent.errors import error_json


class TestErrorJson:
    """Tests for error_json()."""

    def test_basic_error(self):
        result = error_json("Something went wrong.")
        parsed = json.loads(result)
        assert parsed == {"error": "Something went wrong."}

    def test_error_with_hint(self):
        result = error_json(
            "No workflow loaded.",
            hint="Load a workflow first with load_workflow.",
        )
        parsed = json.loads(result)
        assert parsed == {
            "error": "No workflow loaded.",
            "hint": "Load a workflow first with load_workflow.",
        }

    def test_error_with_context_kwargs(self):
        result = error_json(
            "Model directory not found.",
            hint="Choose one of the available types.",
            available=["checkpoints", "loras", "vae"],
        )
        parsed = json.loads(result)
        assert parsed == {
            "error": "Model directory not found.",
            "hint": "Choose one of the available types.",
            "context": {
                "available": ["checkpoints", "loras", "vae"],
            },
        }

    def test_sort_keys(self):
        """JSON keys are sorted for determinism."""
        result = error_json("fail", hint="try again", z_last="z", a_first="a")
        keys = list(json.loads(result).keys())
        assert keys == sorted(keys)

    def test_no_hint_no_context(self):
        """When hint is None and no context, only 'error' key is present."""
        result = error_json("boom")
        parsed = json.loads(result)
        assert list(parsed.keys()) == ["error"]

    def test_hint_none_excluded(self):
        """Explicit hint=None should not produce a 'hint' key."""
        result = error_json("boom", hint=None)
        parsed = json.loads(result)
        assert "hint" not in parsed

    def test_empty_context_excluded(self):
        """No **context kwargs should not produce a 'context' key."""
        result = error_json("boom", hint="try again")
        parsed = json.loads(result)
        assert "context" not in parsed

    def test_multiple_context_kwargs(self):
        result = error_json(
            "Node not found.",
            hint="Check the name.",
            searched_sources=["registry", "civitai"],
            similar=["KSampler", "KSamplerAdvanced"],
        )
        parsed = json.loads(result)
        assert parsed["context"]["searched_sources"] == [
            "registry", "civitai",
        ]
        assert parsed["context"]["similar"] == [
            "KSampler", "KSamplerAdvanced",
        ]

    def test_returns_string(self):
        """error_json always returns a str, not bytes or dict."""
        result = error_json("test")
        assert isinstance(result, str)

    def test_valid_json(self):
        """Output is always valid JSON."""
        result = error_json(
            "Complex error with 'quotes' and \"doubles\".",
            hint="Check the\nnewlines too.",
        )
        parsed = json.loads(result)  # should not raise
        assert "error" in parsed

